CREATE TABLE "profile" (
  "id" uuid PRIMARY KEY DEFAULT (gen_random_uuid()),
  "email" text UNIQUE NOT NULL,
  "password_hash" text NOT NULL,
  "api_token" uuid NOT NULL DEFAULT (gen_random_uuid()),
  "first_name" text NOT NULL,
  "last_name" text NOT NULL,
  "country" text NOT NULL,
  "state" text NOT NULL,
  "city" text,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "xp_event" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" uuid NOT NULL,
  "topic_id" integer,
  "exam_id" integer,
  "points" integer NOT NULL,
  "earned_at" timestamptz NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "daily_activity" (
  "user_id" uuid NOT NULL,
  "activity_date" date NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  PRIMARY KEY ("user_id", "activity_date")
);

CREATE UNIQUE INDEX ON "xp_event" ("user_id", "topic_id");

CREATE UNIQUE INDEX ON "xp_event" ("user_id", "exam_id");

CREATE INDEX ON "xp_event" ("user_id");

COMMENT ON TABLE "profile" IS 'Un participante. XP, racha y nivel NO se guardan aquí: se calculan en la vista leaderboard.';

COMMENT ON COLUMN "profile"."id" IS 'UUID del participante. Lo genera el servidor al registrarse y la app lo guarda como user.id en SQLite.';

COMMENT ON COLUMN "profile"."email" IS 'Correo electrónico en minúsculas. Único. Debe contener @ (mínimo 3 caracteres).';

COMMENT ON COLUMN "profile"."password_hash" IS 'Contraseña con hash bcrypt, generado EN EL SERVIDOR (crypt + gen_salt). Nunca se guarda ni se devuelve en texto plano.';

COMMENT ON COLUMN "profile"."api_token" IS 'Llave que la app recibe al registrarse o iniciar sesión y manda en cada llamada (junto con el id) para demostrar que es el dueño del perfil.';

COMMENT ON COLUMN "profile"."first_name" IS 'Nombre(s). Mínimo 3 caracteres. Se muestra en el ranking.';

COMMENT ON COLUMN "profile"."last_name" IS 'Apellidos. Mínimo 3 caracteres.';

COMMENT ON COLUMN "profile"."country" IS 'País (requerido).';

COMMENT ON COLUMN "profile"."state" IS 'Estado (requerido).';

COMMENT ON COLUMN "profile"."city" IS 'Ciudad (opcional).';

COMMENT ON COLUMN "profile"."created_at" IS 'Fecha de registro.';

COMMENT ON COLUMN "profile"."updated_at" IS 'Última modificación (trigger automático).';

COMMENT ON TABLE "xp_event" IS 'Libro de movimientos. Da el XP total, los temas completados y los exámenes aprobados (nivel).';

COMMENT ON COLUMN "xp_event"."id" IS 'Identificador del movimiento de XP.';

COMMENT ON COLUMN "xp_event"."user_id" IS 'Participante que ganó los puntos.';

COMMENT ON COLUMN "xp_event"."topic_id" IS 'Si el XP vino de un tema (+5): id del tema en el catálogo LOCAL de SQLite (sin llave foránea).';

COMMENT ON COLUMN "xp_event"."exam_id" IS 'Si el XP vino de un examen (+100): id del examen en SQLite (sin llave foránea). Si vino de un tema, queda NULL.';

COMMENT ON COLUMN "xp_event"."points" IS 'Puntos: 5 por tema, 100 por examen (CHECK).';

COMMENT ON COLUMN "xp_event"."earned_at" IS 'Cuándo los ganó en su dispositivo.';

COMMENT ON COLUMN "xp_event"."created_at" IS 'Cuándo llegó al servidor.';

COMMENT ON COLUMN "xp_event"."updated_at" IS 'Última modificación (trigger).';

COMMENT ON TABLE "daily_activity" IS 'Base de la racha: días consecutivos que terminan hoy o ayer.';

COMMENT ON COLUMN "daily_activity"."user_id" IS 'Participante activo ese día.';

COMMENT ON COLUMN "daily_activity"."activity_date" IS 'Día con actividad (día local del usuario).';

COMMENT ON COLUMN "daily_activity"."created_at" IS 'Cuándo llegó al servidor.';

COMMENT ON COLUMN "daily_activity"."updated_at" IS 'Última modificación (trigger).';

ALTER TABLE "xp_event" ADD FOREIGN KEY ("user_id") REFERENCES "profile" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "daily_activity" ADD FOREIGN KEY ("user_id") REFERENCES "profile" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;
